VOWELS = "aeiou"


def _translate_word(word):
    # Rule 1: begins with a vowel (or the special cases "xr" / "yt")
    if word[0] in VOWELS or word[:2] in ("xr", "yt"):
        return word + "ay"

    # Find where the consonant cluster ends: the first vowel, or a "y"
    # that is not the first letter (Rules 2 and 4).
    for i in range(1, len(word)):
        if word[i] in VOWELS or word[i] == "y":
            break
    else:
        i = len(word)

    # Rule 3: if the cluster ends in "qu", move the "qu" along with it.
    if word[i - 1 : i + 1] == "qu":
        i += 1

    return word[i:] + word[:i] + "ay"


def translate(text):
    return " ".join(_translate_word(word) for word in text.split())
